cssCode:
.scroll-text-container {
  height: 200vh;
  display: flex; flex-direction: column; align-items: center;
}
.sticky-text-wrap {
  position: sticky; top: 40vh;
  display: flex; gap: 10px; overflow: hidden;
}
.split-word {
  font-size: 40px; font-weight: 900; font-family: sans-serif;
  color: #ff007f;
  transform: translateY(100%);
  transition: transform 0.6s cubic-bezier(0.175, 0.885, 0.32, 1.275);
}
.split-word.revealed { transform: translateY(0); }

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;overflow-y:auto;background:transparent;';

const wrap = document.createElement('div');
wrap.className = 'scroll-text-container';

const dummySpace = document.createElement('div');
dummySpace.style.height = '30vh';
dummySpace.innerHTML = '<p style="color:#777; text-align:center;">SCROLL DOWN ↓</p>';

const stickyWrap = document.createElement('div');
stickyWrap.className = 'sticky-text-wrap';

const words = ['MOTION', 'ZYNC', 'ANIMATION'];
const wordEls = [];

words.forEach(w => {
  const span = document.createElement('div');
  span.className = 'split-word';
  span.innerText = w;
  wordEls.push(span);
  stickyWrap.appendChild(span);
});

wrap.appendChild(dummySpace);
wrap.appendChild(stickyWrap);
c.appendChild(wrap);

c.addEventListener('scroll', () => {
  const scrollPos = c.scrollTop;
  wordEls.forEach((el, index) => {
    if (scrollPos > 50 + (index * 40)) {
      el.classList.add('revealed');
    } else {
      el.classList.remove('revealed');
    }
  });
});
